On'); ?></span><select name="waiting_on"><?php foreach(array('internal','customer','supplier','factory','forwarder','customs','none') as $w){ ?><option value="<?php echo $w; ?>"<?php echo $v('waiting_on','internal')===$w?' selected':''; ?>><?php echo $langs->trans('Party_'.$w); ?></option><?php } ?></select></label><label class="cpo-field"><span><?php echo $langs->trans('NextAction'); ?></span><input name="next_action" value="<?php echo dol_escape_htmltag($v('next_action')); ?>"></label><label class="cpo-field"><span><?php echo $langs->trans('Deadline'); ?></span><input type="datetime-local" name="date_deadline" value="<?php echo $v('date_deadline')?date('Y-m-d\TH:i',strtotime($v('date_deadline'))):''; ?>"></label></div></section>
